protocol=dict(frozen_at=time.time(),architecture='Local-corpus CRAG adaptation; independent paper-based implementation',pilot_models=['Llama3.1 8B BF16'],questions=335,key='official row_index; original question verbatim',corpus_records=122745,known_limitations='Benchmark-informed corpus with four cross-ID overlaps; not leakage-free',source=dict(paper='https://arxiv.org/abs/2401.15884',inspected_repo_commit='de7c2961ae624a1483a138c5798e1f6d0c4fb0e0',implementation='Independent local implementation, no upstream repository source copied or redistributed',evaluator='Author README-linked T5-large sequence regression safetensors; frozen SHA manifest'),adaptations=['Use frozen mixed-pool dense top5 and cached BM25 top5 instead of web expansion and search-query rewriting','Evaluate explicitly excerpted first256 source words; full question retained in reader; evaluator-only question256/stride192 and document windows cover all source tokens within512, document score=max pair-window regression score','Group complete sentences in threes; split long groups into token windows; filter score>-.5 and stable top5 strips; no unfiltered evidence fallback','Keep identical original benchmark reader and source metadata; original dense335-message parity required; final generation follows our shared benchmark settings'],thresholds=dict(upper=.59,lower=-.99,provenance='Published PopQA thresholds fixed before benchmark inference; not tuned to335 labels'),branches=dict(correct='Refine dense top5 only',incorrect='Replace dense evidence with cached BM25 top5, then refine',ambiguous='Stable union dense top5+cached BM25 top5, then refine'),empty_evidence='Original reader with no references; this is declared pipeline behavior, never an answer retry',evaluator=dict(dtype='FP32',devices=['cuda:0','cuda:1'],batch_size=8,max_sequence_tokens=512,CPU_fallback=False,strict_checkpoint_loading=True),generation=dict(max_tokens=2048,temperature=.1,seed=0,top_p=1,enable_thinking=True,JSON_fallback=False,answer_retries=0),workers_per_GPU=8,workers_total=16,capacity_gate='All335 serving-token counts plus2048; each8-longest-request budget must fit measured KV token capacity;16 synthetic requests',GPU_preparation_gate='Both GPU strict model load, finite deterministic synthetic pair scores, complete long-text partition coverage;335 original dense reader parity before final generation',scoring='Catalog-normalized strict CWE accuracy, full335 denominator; no hierarchy credit; gold opened only after335 prediction ledger frozen',recovery='At most2 infrastructure restarts; preserve completed per-row predictions; no semantic/length retries; preparation checkpoint records source/model identities in this frozen manifest',resource_schedule='Wait current Fusion owner terminal/dead and both GPUs free, evaluate/refine all335 on both GPUs, release evaluators, start two independent Llama replicas',sha256=manifest)
